const dialog=document.querySelector('#info-dialog');
const dialogBody=document.querySelector('#dialog-body');
const panels={
 signin:`<span class="dialog-kicker">PLATFORM ACCESS</span><h2>One account.<br>Your utility workspaces.</h2><p>Provider sign-in is not connected yet. These are placeholders for the planned signup and sign-in experience.</p><div class="provider-buttons">${['Apple','Google','Facebook','Microsoft'].map(p=>`<button disabled>Continue with ${p}<small>Coming soon</small></button>`).join('')}</div><p>No account or session is created in this preview.</p>`,
 catalog:`<span class="dialog-kicker">DATABASE-DRIVEN PACKAGES · PLANNED</span><h2>A catalog that stays connected.</h2><p>These cards currently load a separate sample catalog file. The ERP database and public catalog endpoint are not yet implemented.</p><div class="catalog-path">Published packages → Versioned modules → Public prices → Catalog API → Package cards</div><p>The production page will show approved offers from database records. Existing tenant subscriptions and negotiated prices stay private.</p><span class="dialog-tag">Preview prices intentionally not set</span>`,
 staffing:`<span class="dialog-kicker">MANAGED OPERATIONS · PLANNED</span><h2>People where you need them.</h2><p>The planned model lets your utility contract customer service, billing, metering, and field support through approved providers.</p><ul><li>Time-bounded assignments inside your workspace.</li><li>Defined roles and scopes, with separate approvals.</li><li>An accountable utility representative, even with no internal employees.</li></ul><p>Staffing availability, scope, fees, and qualifications require an agreed service contract. No worker is assigned from this preview.</p>`,
 status:`<span class="dialog-kicker">PROJECT DIRECTION</span><h2>From foundation<br>to a working utility.</h2><ul><li><b>Phase 1:</b> architecture, ERD, database standards, subscriptions, staffing, and this visual preview.</li><li><b>Phase 2:</b> application foundation, authentication boundaries, tenant isolation, and catalog database.</li><li><b>Phase 3:</b> a complete synthetic meter-to-cash cycle.</li><li><b>Phases 4–5:</b> operational workflows and pilot readiness.</li></ul><p>You are viewing a concept preview. Live ERP workflows, payments, and provider sign-in are not connected.</p>`
};
function openDialog(content){dialogBody.innerHTML=content;dialog.showModal();}
document.querySelectorAll('[data-dialog]').forEach(b=>b.addEventListener('click',()=>openDialog(panels[b.dataset.dialog])));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('header nav').classList.toggle('open',open);});
document.querySelectorAll('header nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');document.querySelector('header nav').classList.remove('open');}));
const steps=[
 {title:'Start with the right connection.',icon:'♙',name:'Santos Household',sub:'Sample customer · Residential connection',status:'Registered',fields:[['Service point','SP-DEMO-001'],['Account','ACC-DEMO-001'],['Customer type','Residential'],['Next step','Meter installation']]},
 {title:'Review the reading before the bill.',icon:'ϟ',name:'Meter reading captured',sub:'Sample meter · MT-DEMO-001',status:'For review',fields:[['Opening reading','1,000 kWh'],['Closing reading','1,150 kWh'],['Consumption','150 kWh'],['Next step','Validate reading']]},
 {title:'Prepare. Review. Approve.',icon:'▤',name:'A traceable billing calculation',sub:'Demonstration tariff · Not an approved rate',status:'Draft',fields:[['Consumption charge','₱17.50'],['Fixed charge','₱5.00'],['Sample bill total','₱22.50'],['Next step','Independent approval']]},
 {title:'Keep the account in balance.',icon:'✓',name:'Payment allocated to the bill',sub:'Illustrative receipt · No real payment',status:'Partial payment',fields:[['Sample invoice','₱22.50'],['Recorded payment','₱10.00'],['Outstanding balance','₱12.50'],['Next step','Account statement']]}
];
const tabs=[...document.querySelectorAll('[data-step]')];
function selectStep(n,focus=false){tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===n));t.tabIndex=i===n?0:-1;});const s=steps[n],p=document.querySelector('#workflow-panel');p.setAttribute('aria-labelledby',tabs[n].id);p.innerHTML=`<span class="micro">SERVICE CYCLE / ${String(n+1).padStart(2,'0')}</span><h3>${s.title}</h3><div class="preview-record"><span class="record-icon">${s.icon}</span><div><b>${s.name}</b><p>${s.sub}</p></div><span class="record-status">${s.status}</span></div><div class="record-details">${s.fields.map(f=>`<div><span>${f[0]}</span><b>${f[1]}</b></div>`).join('')}</div><p>ILLUSTRATIVE WORKFLOW · SYNTHETIC RECORDS</p>`;if(focus)tabs[n].focus();}
tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectStep(i));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();selectStep(n,true);}});});selectStep(0);
function node(tag,cls,text){const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;}
async function loadCatalog(){const grid=document.querySelector('#package-grid');try{const res=await fetch('assets/catalog.json');if(!res.ok)throw new Error('catalog');const catalog=await res.json();if(!Array.isArray(catalog.packages))throw new Error('shape');grid.replaceChildren();if(!catalog.packages.length){grid.append(node('p','error-state','Packages are being prepared. No approved offers are published yet.'));return;}catalog.packages.forEach(p=>{const card=node('article',`package-card${p.featured?' featured':''}`);card.append(node('span','package-badge',p.badge),node('h3','',p.name),node('p','summary',p.summary),node('div','price','Let’s discuss'),node('p','price-note','Price & terms to be confirmed'));const b=node('button','button package-select','Explore this package');b.append(node('span','','→'));b.addEventListener('click',()=>{openDialog(panels.status);dialogBody.querySelector('h2').textContent=`Explore ${p.name}`;dialogBody.querySelector('ul').remove();dialogBody.querySelector('p').textContent='This is a proposed package, with pricing and commercial terms still to be defined. No subscription is created. You can review its planned module inclusions on the page.';});card.append(b,node('p','includes-label','PLANNED INCLUSIONS'));const list=node('ul');p.modules.forEach(m=>list.append(node('li','',m)));card.append(list);grid.append(card);});}catch{grid.replaceChildren();const box=node('div','error-state');box.append(node('p','','We couldn’t load the package preview. Please retry.'));const retry=node('button','button small','Retry');retry.addEventListener('click',loadCatalog);box.append(retry);grid.append(box);}}
loadCatalog();
